const searchBrain = `-- name: SearchBrain :many
SELECT e.id, e.scope, e.project_id, e.component_key, e.user_id, e.agent_id, e.kind, e.topic, e.title, e.content, e.visibility, e.status, e.lineage, e.version, e.supersedes, e.valid_from, e.valid_until, e.confidence, e.source, e.source_task_id, e.source_conversation_id, e.source_private, e.position, e.condensed_from, e.archived_at, e.created_by_kind, e.created_by, e.approved_by, e.approved_at, e.created_at, e.updated_at, (CASE WHEN $1::text = '' THEN 0
             ELSE ts_rank(to_tsvector('simple', e.title || ' ' || e.content), websearch_to_tsquery('simple', $1::text)) END)::real AS rank
FROM brain_entries e
WHERE ($1::text = '' OR to_tsvector('simple', e.title || ' ' || e.content) @@ websearch_to_tsquery('simple', $1::text))
  AND (cardinality($2::text[]) = 0 OR e.scope = ANY($2::text[]))
  AND (cardinality($3::text[]) = 0 OR e.kind = ANY($3::text[]))
  AND (cardinality($4::text[]) = 0 OR e.status = ANY($4::text[]))
  AND ($5::uuid IS NULL OR e.project_id = $5::uuid OR e.project_id IS NULL)
  AND ($6::boolean OR e.archived_at IS NULL)
  AND (e.scope = 'workspace' OR e.visibility = 'workspace'
       OR (e.scope IN ('project', 'component', 'agent') AND ($7::boolean OR e.project_id = ANY($8::uuid[])))
       OR (e.scope = 'user' AND (e.user_id = $9::uuid
                                 OR (e.visibility = 'project' AND ($7::boolean OR e.project_id = ANY($8::uuid[]))))))
ORDER BY rank DESC, e.updated_at DESC, e.id
LIMIT $10
`

type SearchBrainParams struct {
	Query           string        `json:"query"`
	Scopes          []string      `json:"scopes"`
	Kinds           []string      `json:"kinds"`
	Statuses        []string      `json:"statuses"`
	ProjectID       pgtype.UUID   `json:"project_id"`
	IncludeArchived bool          `json:"include_archived"`
	EveryProject    bool          `json:"every_project"`
	Projects        []pgtype.UUID `json:"projects"`
	UserID          pgtype.UUID   `json:"user_id"`
	MaxRows         int32         `json:"max_rows"`
}

type SearchBrainRow struct {
	BrainEntry BrainEntry `json:"brain_entry"`
	Rank       float32    `json:"rank"`
}

// Candidates for a reader, by words (websearch syntax) or, without words, the newest first. The
// reach is wider than the rules, never narrower: every row still passes brain.Policy.
func (q *Queries) SearchBrain(ctx context.Context, arg SearchBrainParams) ([]SearchBrainRow, error) {
	rows, err := q.db.Query(ctx, searchBrain,
		arg.Query,
		arg.Scopes,
		arg.Kinds,
		arg.Statuses,
		arg.ProjectID,
		arg.IncludeArchived,
		arg.EveryProject,
		arg.Projects,
		arg.UserID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SearchBrainRow
	for rows.Next() {
		var i SearchBrainRow
		if err := rows.Scan(
			&i.BrainEntry.ID,
			&i.BrainEntry.Scope,
			&i.BrainEntry.ProjectID,
			&i.BrainEntry.ComponentKey,
			&i.BrainEntry.UserID,
			&i.BrainEntry.AgentID,
			&i.BrainEntry.Kind,
			&i.BrainEntry.Topic,
			&i.BrainEntry.Title,
			&i.BrainEntry.Content,
			&i.BrainEntry.Visibility,
			&i.BrainEntry.Status,
			&i.BrainEntry.Lineage,
			&i.BrainEntry.Version,
			&i.BrainEntry.Supersedes,
			&i.BrainEntry.ValidFrom,
			&i.BrainEntry.ValidUntil,
			&i.BrainEntry.Confidence,
			&i.BrainEntry.Source,
			&i.BrainEntry.SourceTaskID,
			&i.BrainEntry.SourceConversationID,
			&i.BrainEntry.SourcePrivate,
			&i.BrainEntry.Position,
			&i.BrainEntry.CondensedFrom,
			&i.BrainEntry.ArchivedAt,
			&i.BrainEntry.CreatedByKind,
			&i.BrainEntry.CreatedBy,
			&i.BrainEntry.ApprovedBy,
			&i.BrainEntry.ApprovedAt,
			&i.BrainEntry.CreatedAt,
			&i.BrainEntry.UpdatedAt,
			&i.Rank,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

